<?php
defined('BASEPATH') OR exit('No direct script access allowed');

class English_course_model extends CI_Model
{
    public function __construct()
    {
        parent::__construct();
        $this->ensure_schema();
        $this->seed_curriculum();
        $this->normalize_answer_positions();
        $this->expand_curriculum_v3();
        $this->build_stage1_v1();
        $this->improve_stage1_v2();
        $this->balance_stage1_assessment_v3();
        $this->add_stage1_varied_practice_v4();
    }

    private function ensure_schema()
    {
        $queries = [
            "CREATE TABLE IF NOT EXISTS english_course_levels (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(40) NOT NULL UNIQUE,title VARCHAR(120) NOT NULL,cefr VARCHAR(20) NULL,subtitle VARCHAR(180) NULL,description TEXT NULL,color VARCHAR(20) NOT NULL DEFAULT '#2476d3',icon VARCHAR(80) NOT NULL DEFAULT 'ti ti-language',sort_order INT UNSIGNED NOT NULL DEFAULT 1,pass_score TINYINT UNSIGNED NOT NULL DEFAULT 70,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NULL ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
            "CREATE TABLE IF NOT EXISTS english_course_units (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,level_id INT UNSIGNED NOT NULL,code VARCHAR(60) NOT NULL UNIQUE,title VARCHAR(140) NOT NULL,subtitle VARCHAR(180) NULL,description TEXT NULL,emoji VARCHAR(20) NULL,sort_order INT UNSIGNED NOT NULL DEFAULT 1,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_ecu_level(level_id),CONSTRAINT fk_ecu_level FOREIGN KEY(level_id) REFERENCES english_course_levels(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
            "CREATE TABLE IF NOT EXISTS english_course_lessons (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,unit_id INT UNSIGNED NOT NULL,code VARCHAR(80) NOT NULL UNIQUE,title VARCHAR(160) NOT NULL,context_label VARCHAR(180) NULL,introduction TEXT NULL,content_json LONGTEXT NOT NULL,sort_order INT UNSIGNED NOT NULL DEFAULT 1,xp_reward INT UNSIGNED NOT NULL DEFAULT 20,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NULL ON UPDATE CURRENT_TIMESTAMP,KEY idx_ecl_unit(unit_id),CONSTRAINT fk_ecl_unit FOREIGN KEY(unit_id) REFERENCES english_course_units(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
            "CREATE TABLE IF NOT EXISTS english_course_tests (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,level_id INT UNSIGNED NOT NULL UNIQUE,title VARCHAR(160) NOT NULL,instructions TEXT NULL,pass_score TINYINT UNSIGNED NOT NULL DEFAULT 70,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_ect_level FOREIGN KEY(level_id) REFERENCES english_course_levels(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
            "CREATE TABLE IF NOT EXISTS english_course_test_questions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,test_id INT UNSIGNED NOT NULL,prompt TEXT NOT NULL,audio_text VARCHAR(255) NULL,choices_json TEXT NOT NULL,correct_index TINYINT UNSIGNED NOT NULL DEFAULT 0,explanation TEXT NULL,sort_order INT UNSIGNED NOT NULL DEFAULT 1,KEY idx_ectq_test(test_id),CONSTRAINT fk_ectq_test FOREIGN KEY(test_id) REFERENCES english_course_tests(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
            "CREATE TABLE IF NOT EXISTS english_course_lesson_progress (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,lesson_id INT UNSIGNED NOT NULL,status ENUM('started','completed') NOT NULL DEFAULT 'started',score TINYINT UNSIGNED NOT NULL DEFAULT 0,completed_at DATETIME NULL,last_opened_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_eclp_user_lesson(user_id,lesson_id),KEY idx_eclp_user(user_id),CONSTRAINT fk_eclp_lesson FOREIGN KEY(lesson_id) REFERENCES english_course_lessons(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
            "CREATE TABLE IF NOT EXISTS english_course_test_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,test_id INT UNSIGNED NOT NULL,score TINYINT UNSIGNED NOT NULL,correct_count INT UNSIGNED NOT NULL,total_questions INT UNSIGNED NOT NULL,is_passed TINYINT(1) NOT NULL DEFAULT 0,answers_json LONGTEXT NULL,started_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,completed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_ecta_user(user_id),KEY idx_ecta_test(test_id),CONSTRAINT fk_ecta_test FOREIGN KEY(test_id) REFERENCES english_course_tests(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
            "CREATE TABLE IF NOT EXISTS english_course_activity_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,lesson_id INT UNSIGNED NOT NULL,step_no SMALLINT UNSIGNED NOT NULL,activity_type VARCHAR(40) NOT NULL,answer_text TEXT NULL,score TINYINT UNSIGNED NOT NULL DEFAULT 0,is_correct TINYINT(1) NOT NULL DEFAULT 0,attempt_count INT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NULL ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_ecaa_user_step(user_id,lesson_id,step_no),KEY idx_ecaa_user(user_id),CONSTRAINT fk_ecaa_lesson FOREIGN KEY(lesson_id) REFERENCES english_course_lessons(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
            "CREATE TABLE IF NOT EXISTS english_course_checkpoint_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,unit_id INT UNSIGNED NOT NULL,score TINYINT UNSIGNED NOT NULL,correct_count INT UNSIGNED NOT NULL,total_questions INT UNSIGNED NOT NULL,is_passed TINYINT(1) NOT NULL DEFAULT 0,answers_json LONGTEXT NULL,completed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_ecca_user(user_id),KEY idx_ecca_unit(unit_id),CONSTRAINT fk_ecca_unit FOREIGN KEY(unit_id) REFERENCES english_course_units(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
            "CREATE TABLE IF NOT EXISTS english_course_stage_review_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,level_id INT UNSIGNED NOT NULL,review_part TINYINT UNSIGNED NOT NULL,score TINYINT UNSIGNED NOT NULL,correct_count INT UNSIGNED NOT NULL,total_questions INT UNSIGNED NOT NULL,is_passed TINYINT(1) NOT NULL DEFAULT 0,answers_json LONGTEXT NULL,completed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_ecsra_user(user_id),KEY idx_ecsra_level(level_id,review_part),CONSTRAINT fk_ecsra_level FOREIGN KEY(level_id) REFERENCES english_course_levels(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci",
            "CREATE TABLE IF NOT EXISTS english_course_settings (setting_key VARCHAR(80) PRIMARY KEY,setting_value TEXT NULL,updated_at DATETIME NULL ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci"
        ];
        foreach ($queries as $sql) $this->db->query($sql);
        if(!$this->db->field_exists('stage_no','english_course_units'))$this->db->query("ALTER TABLE english_course_units ADD stage_no TINYINT UNSIGNED NOT NULL DEFAULT 1 AFTER level_id, ADD KEY idx_ecu_stage(stage_no)");
        if(!$this->db->field_exists('lesson_type','english_course_lessons'))$this->db->query("ALTER TABLE english_course_lessons ADD lesson_type VARCHAR(30) NOT NULL DEFAULT 'dialogue' AFTER context_label");
        if(!$this->db->field_exists('question_type','english_course_test_questions'))$this->db->query("ALTER TABLE english_course_test_questions ADD question_type VARCHAR(30) NOT NULL DEFAULT 'comprehension' AFTER audio_text");
        $defaults=['course_title'=>'English Learning Course','tts_voice'=>'us_female','tts_rate'=>'0.88','show_translation'=>'1','require_level_test'=>'1'];
        foreach($defaults as $key=>$value)$this->db->query("INSERT IGNORE INTO english_course_settings(setting_key,setting_value) VALUES(?,?)",[$key,$value]);
        $this->db->query("UPDATE english_course_settings SET setting_value='us_female' WHERE setting_key='tts_voice' AND setting_value='female'");
    }

